// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.plannerimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.ResourceEstimateimport com.roshan.persona.cognitive.model.SubTaskimport com.roshan.persona.cognitive.model.SubTaskTypeimport com.roshan.persona.cognitive.model.TaskPlanimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Task Decomposer (Module 7 v2 — Step 7.3). * * Decomposes a complex user goal into 3-7 sub-tasks using LLM. * * ## Algorithm * * 1. Build a prompt: "Decompose this task into [min]-[max] sub-tasks: *    [goal]. Return each sub-task as: id | description | type | tools". * 2. Call LLM (Module 4). * 3. Parse the response into [SubTask] objects. * 4. Build a dependency map (LLM specifies dependencies in the prompt). * * For v1, we use a [DecomposerLlm] interface so tests inject a fake. * The real impl wires to Module 4's LLM provider. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§TaskPlanner</a> */class TaskDecomposer(    private val llm: DecomposerLlm,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Decompose [goal] into sub-tasks.     *     * @param goal the user's goal ("Plan a 3-day Goa trip under ₹15,000").     * @return list of sub-tasks (3-7), or empty list if decomposition failed.     */    suspend fun decompose(goal: String): List<SubTask> = withContext(dispatcher) {        val response = try {            llm.decompose(goal, config.minSubTasks, config.maxSubTasks)        } catch (t: Throwable) {            return@withContext emptyList()        }        parseResponse(response)    }    /**     * Parse the LLM response into [SubTask] objects.     *     * Expected format (one sub-task per line):     * ```     * research_flights | Research flights from BLR to GOI | RESEARCH | search_web     * find_hotels | Find hotels in Goa | RESEARCH | search_web     * plan_budget | Calculate total budget | DECISION | recall_memory     * ```     */    internal fun parseResponse(response: String): List<SubTask> {        if (response.isBlank()) return emptyList()        val subTasks = mutableListOf<SubTask>()        for (line in response.lines()) {            val trimmed = line.trim()            if (trimmed.isBlank() || trimmed.startsWith("#")) continue            val parts = trimmed.split("|").map { it.trim() }            if (parts.size < 2) continue            val id = parts[0]            val description = parts[1]            val type = parts.getOrNull(2)?.let { parseType(it) } ?: SubTaskType.RESEARCH            val tools = parts.getOrNull(3)?.split(",")?.map { it.trim() }?.filter { it.isNotBlank() } ?: emptyList()            if (id.isNotBlank() && description.isNotBlank()) {                subTasks.add(SubTask(                    id = id,                    description = description,                    type = type,                    requiredTools = tools,                ))            }        }        // Clamp to min/max.        return subTasks.take(config.maxSubTasks)    }    private fun parseType(text: String): SubTaskType? = when (text.uppercase().trim()) {        "RESEARCH" -> SubTaskType.RESEARCH        "DECISION" -> SubTaskType.DECISION        "ACTION" -> SubTaskType.ACTION        "VERIFICATION" -> SubTaskType.VERIFICATION        "SYNTHESIS" -> SubTaskType.SYNTHESIS        else -> null    }}/** * LLM interface for task decomposition. * * Real implementation wires to Module 4 (LlmProvider). Tests inject a fake. */fun interface DecomposerLlm {    /**     * Decompose [goal] into [minTasks]-[maxTasks] sub-tasks.     *     * @return raw text response (one sub-task per line, pipe-delimited).     */    suspend fun decompose(goal: String, minTasks: Int, maxTasks: Int): String}// ──────────────────────────────────────────────────────────────────────────/** * NOUS — Task Planner (Module 7 v2 — Step 7.3, tool-aware). * * Main entry point for task planning. Combines: *  1. [TaskDecomposer] — LLM-based sub-task generation. *  2. [DependencyGraph] — topological sort + parallel groups. *  3. Tool-aware filtering — removes sub-tasks whose required tools are unavailable. *  4. Resource estimation — time + cost + permissions. * * ## Tool-aware planning (v2 addition) * * Before returning the plan, the planner checks each sub-task's [SubTask.requiredTools] * against the available tools. Sub-tasks with unavailable tools are moved to * [TaskPlan.removedSubTasks] with a note. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§TaskPlanner</a> */class TaskPlanner(    private val decomposer: TaskDecomposer,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Decompose [goal] into a [TaskPlan].     *     * @param goal the user's goal.     * @param availableToolIds set of tool IDs that are currently available.     * @return a task plan, or null if decomposition failed.     */    suspend fun decompose(        goal: String,        availableToolIds: Set<String> = emptySet(),    ): TaskPlan? = withContext(dispatcher) {        // 1. Decompose into sub-tasks.        val rawSubTasks = decomposer.decompose(goal)        if (rawSubTasks.isEmpty()) return@withContext null        // 2. Filter out sub-tasks with unavailable tools.        val (feasible, removed) = if (availableToolIds.isEmpty()) {            rawSubTasks to emptyList()  // no tool filtering if no tools specified        } else {            rawSubTasks.partition { subTask ->                subTask.requiredTools.all { it in availableToolIds }            }        }        if (feasible.isEmpty()) return@withContext null        // 3. Build dependency map (v1: no dependencies from LLM — all parallel).        // Future: LLM specifies dependencies in the decomposition prompt.        val dependencies = emptyMap<String, List<String>>()        // 4. Compute parallel groups.        val parallelGroups = DependencyGraph.parallelGroups(            subTaskIds = feasible.map { it.id },            dependencies = dependencies,        ) ?: emptyList()        // 5. Estimate resources.        val estimatedTimeMs = feasible.sumOf { it.estimatedTimeMs }        val estimatedCostUsd = feasible.size * 0.005f  // ~$0.005 per LLM call        val requiredPermissions = feasible.flatMap { it.requiredTools }.distinct()        val llmCallsEstimated = feasible.size        val resources = ResourceEstimate(            estimatedTimeMs = estimatedTimeMs,            estimatedCostUsd = estimatedCostUsd,            requiredPermissions = requiredPermissions,            llmCallsEstimated = llmCallsEstimated,        )        TaskPlan(            rootGoal = goal,            subTasks = feasible,            dependencies = dependencies,            parallelGroups = parallelGroups,            estimatedResources = resources,            removedSubTasks = removed,        )    }    /**     * Re-plan after a sub-task failure (v2 — ReplanningEngine calls this).     *     * Removes the failed sub-task + any tasks that depend on it, then     * returns the updated plan.     */    suspend fun replan(        originalPlan: TaskPlan,        failedSubTaskId: String,        failureReason: String,    ): TaskPlan? = withContext(dispatcher) {        val remaining = originalPlan.subTasks.filter { it.id != failedSubTaskId }        if (remaining.isEmpty()) return@withContext null        // Remove any tasks that depend on the failed task.        val toRemove = mutableSetOf<String>()        findDependents(failedSubTaskId, originalPlan.dependencies, toRemove)        val feasible = remaining.filter { it.id !in toRemove }        if (feasible.isEmpty()) return@withContext null        originalPlan.copy(            subTasks = feasible,            parallelGroups = DependencyGraph.parallelGroups(                feasible.map { it.id },                originalPlan.dependencies.filterKeys { it in feasible.map { s -> s.id } },            ) ?: emptyList(),        )    }    /** Recursively find all tasks that depend on [taskId]. */    private fun findDependents(        taskId: String,        dependencies: Map<String, List<String>>,        result: MutableSet<String>,    ) {        for ((task, deps) in dependencies) {            if (taskId in deps && task !in result) {                result.add(task)                findDependents(task, dependencies, result)            }        }    }}
